    /// <summary>An array of strings for prefixes to be match.</summary>
    [JsonIgnore]
    public IList<string>? FiltersPrefixMatch
    {
        get => Definition.Filters?.PrefixMatch;
        set
        {
            Definition ??= new ManagementPolicyDefinition();
            Definition.Filters ??= new ManagementPolicyFilter();
            Definition.Filters.PrefixMatch = value;
        }
    }

    /// <summary>An array of predefined enum values. Currently blockBlob supports all tiering and delete actions. Only delete actions are supported for appendBlob.</summary>
    [JsonIgnore]
    public IList<string>? FiltersBlobTypes
    {
        get => Definition.Filters?.BlobTypes;
        set
        {
            Definition ??= new ManagementPolicyDefinition();
            Definition.Filters ??= new ManagementPolicyFilter();
            Definition.Filters.BlobTypes = value!;
        }
    }

    /// <summary>An array of blob index tag based filters, there can be at most 10 tag filters</summary>
    [JsonIgnore]
    public IList<TagFilter>? FiltersBlobIndexMatch
    {
        get => Definition.Filters?.BlobIndexMatch;
        set
        {
            Definition ??= new ManagementPolicyDefinition();
            Definition.Filters ??= new ManagementPolicyFilter();
            Definition.Filters.BlobIndexMatch = value;
        }
    }
}
